import json
import logging
import os
import threading
from contextlib import contextmanager
from functools import lru_cache
from typing import Any, Dict, List, Optional

import httpx
import pymysql
from flask import Flask, jsonify, request, send_from_directory
from flask_cors import CORS
from openai import OpenAI
from pymysql.cursors import DictCursor
from werkzeug.exceptions import BadRequest, HTTPException

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DEFAULT_CONVERSATION_TITLE = "New Chat"

app = Flask(__name__, static_folder=None)
app.config["JSON_SORT_KEYS"] = False

logging.basicConfig(
    level=os.getenv("LOG_LEVEL", "INFO").upper(),
    format="%(asctime)s %(levelname)s %(name)s %(message)s",
)

_schema_initialized = False
_schema_lock = threading.Lock()


class ApiError(Exception):
    def __init__(self, message: str, status_code: int = 400) -> None:
        super().__init__(message)
        self.message = message
        self.status_code = status_code


def get_env_str(name: str, default: Optional[str] = None, required: bool = False) -> str:
    value = os.getenv(name, default)
    if value is None:
        if required:
            raise ApiError(f"Missing required environment variable: {name}", 500)
        return ""
    if isinstance(value, str):
        value = value.strip()
    if required and value == "":
        raise ApiError(f"Missing required environment variable: {name}", 500)
    return value


def get_env_int(
    name: str,
    default: int,
    minimum: Optional[int] = None,
    maximum: Optional[int] = None,
) -> int:
    raw = os.getenv(name)
    value = default if raw is None or str(raw).strip() == "" else None
    if value is None:
        try:
            value = int(str(raw).strip())
        except ValueError as exc:
            raise ApiError(f"Invalid integer environment variable: {name}", 500) from exc
    if minimum is not None and value < minimum:
        raise ApiError(f"Environment variable {name} must be >= {minimum}", 500)
    if maximum is not None and value > maximum:
        raise ApiError(f"Environment variable {name} must be <= {maximum}", 500)
    return value


def get_env_bool(name: str, default: bool = False) -> bool:
    raw = os.getenv(name)
    if raw is None:
        return default
    value = str(raw).strip().lower()
    if value in {"1", "true", "yes", "y", "on"}:
        return True
    if value in {"0", "false", "no", "n", "off"}:
        return False
    raise ApiError(f"Invalid boolean environment variable: {name}", 500)


def get_cors_origins() -> Any:
    raw = os.getenv("CORS_ORIGINS", "*").strip()
    if raw == "*":
        return "*"
    origins = [item.strip() for item in raw.split(",") if item.strip()]
    return origins or "*"


CORS(app, resources={r"/api/*": {"origins": get_cors_origins()}})


def build_db_ssl_options() -> Optional[Dict[str, Any]]:
    if get_env_bool("DB_SSL_DISABLED", False):
        return None
    ssl_ca = os.getenv("DB_SSL_CA")
    ssl_cert = os.getenv("DB_SSL_CERT")
    ssl_key = os.getenv("DB_SSL_KEY")
    ssl_check_hostname = get_env_bool("DB_SSL_CHECK_HOSTNAME", True)
    ssl_options: Dict[str, Any] = {}
    if ssl_ca:
        ssl_options["ca"] = ssl_ca
    if ssl_cert:
        ssl_options["cert"] = ssl_cert
    if ssl_key:
        ssl_options["key"] = ssl_key
    ssl_options["check_hostname"] = ssl_check_hostname
    return ssl_options


def build_db_kwargs() -> Dict[str, Any]:
    kwargs: Dict[str, Any] = {
        "host": get_env_str("DB_HOST", required=True),
        "port": get_env_int("DB_PORT", 4000, 1, 65535),
        "user": get_env_str("DB_USERNAME", required=True),
        "password": get_env_str("DB_PASSWORD", required=True),
        "database": get_env_str("DB_DATABASE", required=True),
        "charset": "utf8mb4",
        "cursorclass": DictCursor,
        "autocommit": False,
        "connect_timeout": get_env_int("DB_CONNECT_TIMEOUT", 10, 1, 300),
        "read_timeout": get_env_int("DB_READ_TIMEOUT", 30, 1, 3600),
        "write_timeout": get_env_int("DB_WRITE_TIMEOUT", 30, 1, 3600),
    }
    ssl_options = build_db_ssl_options()
    if ssl_options is not None:
        kwargs["ssl"] = ssl_options
    return kwargs


@contextmanager
def db_connection():
    conn = pymysql.connect(**build_db_kwargs())
    try:
        yield conn
    finally:
        try:
            conn.close()
        except Exception:
            pass


def table_exists(cur: DictCursor, table_name: str) -> bool:
    cur.execute(
        """
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = DATABASE() AND table_name = %s
        LIMIT 1
        """,
        (table_name,),
    )
    return cur.fetchone() is not None


def column_exists(cur: DictCursor, table_name: str, column_name: str) -> bool:
    cur.execute(
        """
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = DATABASE()
          AND table_name = %s
          AND column_name = %s
        LIMIT 1
        """,
        (table_name, column_name),
    )
    return cur.fetchone() is not None


def index_exists(cur: DictCursor, table_name: str, index_name: str) -> bool:
    cur.execute(
        """
        SELECT 1
        FROM information_schema.statistics
        WHERE table_schema = DATABASE()
          AND table_name = %s
          AND index_name = %s
        LIMIT 1
        """,
        (table_name, index_name),
    )
    return cur.fetchone() is not None


def constraint_exists(cur: DictCursor, table_name: str, constraint_name: str) -> bool:
    cur.execute(
        """
        SELECT 1
        FROM information_schema.table_constraints
        WHERE table_schema = DATABASE()
          AND table_name = %s
          AND constraint_name = %s
        LIMIT 1
        """,
        (table_name, constraint_name),
    )
    return cur.fetchone() is not None


def init_db() -> None:
    with db_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS conversations (
                    id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
                    title VARCHAR(255) NOT NULL,
                    auto_title TINYINT(1) NOT NULL DEFAULT 1,
                    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
                    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
                """
            )
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS messages (
                    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
                    conversation_id INT UNSIGNED NOT NULL,
                    role ENUM('user', 'assistant') NOT NULL,
                    content MEDIUMTEXT NOT NULL,
                    reasoning MEDIUMTEXT NULL,
                    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
                    CONSTRAINT fk_messages_conversation
                        FOREIGN KEY (conversation_id) REFERENCES conversations(id)
                        ON DELETE CASCADE
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
                """
            )

            if not column_exists(cur, "conversations", "auto_title"):
                cur.execute(
                    "ALTER TABLE conversations ADD COLUMN auto_title TINYINT(1) NOT NULL DEFAULT 1 AFTER title"
                )

            cur.execute(
                """
                ALTER TABLE conversations
                    MODIFY COLUMN title VARCHAR(255) NOT NULL,
                    MODIFY COLUMN created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
                    MODIFY COLUMN updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)
                """
            )

            if not index_exists(cur, "conversations", "idx_conversations_updated_at_id"):
                cur.execute(
                    "CREATE INDEX idx_conversations_updated_at_id ON conversations (updated_at DESC, id DESC)"
                )

            cur.execute(
                """
                ALTER TABLE messages
                    MODIFY COLUMN role ENUM('user', 'assistant') NOT NULL,
                    MODIFY COLUMN content MEDIUMTEXT NOT NULL,
                    MODIFY COLUMN reasoning MEDIUMTEXT NULL,
                    MODIFY COLUMN created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
                """
            )

            if not constraint_exists(cur, "messages", "fk_messages_conversation"):
                cur.execute(
                    """
                    ALTER TABLE messages
                    ADD CONSTRAINT fk_messages_conversation
                    FOREIGN KEY (conversation_id) REFERENCES conversations(id)
                    ON DELETE CASCADE
                    """
                )

            if not index_exists(cur, "messages", "idx_messages_conversation_created_id"):
                cur.execute(
                    "CREATE INDEX idx_messages_conversation_created_id ON messages (conversation_id, created_at, id)"
                )

        conn.commit()


def initialize_once() -> None:
    global _schema_initialized
    if _schema_initialized:
        return
    with _schema_lock:
        if _schema_initialized:
            return
        init_db()
        _schema_initialized = True


def parse_json_body() -> Dict[str, Any]:
    if not request.is_json:
        raise ApiError("Request body must be application/json", 415)
    try:
        data = request.get_json(force=False, silent=False, cache=False)
    except BadRequest as exc:
        raise ApiError("Invalid JSON body", 400) from exc
    if not isinstance(data, dict):
        raise ApiError("JSON body must be an object", 400)
    return data


def parse_query_int(name: str, default: int, minimum: int, maximum: int) -> int:
    raw = request.args.get(name, "")
    if raw == "":
        return default
    try:
        value = int(raw)
    except ValueError as exc:
        raise ApiError(f"Invalid query parameter: {name}", 400) from exc
    if value < minimum or value > maximum:
        raise ApiError(f"Query parameter {name} must be between {minimum} and {maximum}", 400)
    return value


def normalize_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, list):
        parts: List[str] = []
        for item in value:
            if isinstance(item, str):
                if item.strip():
                    parts.append(item.strip())
            elif isinstance(item, dict):
                text_value = item.get("text")
                if isinstance(text_value, str) and text_value.strip():
                    parts.append(text_value.strip())
                elif isinstance(text_value, dict):
                    inner_value = text_value.get("value")
                    if isinstance(inner_value, str) and inner_value.strip():
                        parts.append(inner_value.strip())
                else:
                    value_field = item.get("value")
                    if isinstance(value_field, str) and value_field.strip():
                        parts.append(value_field.strip())
            else:
                text = str(item).strip()
                if text:
                    parts.append(text)
        return "\n".join(parts).strip()
    if isinstance(value, dict):
        text_value = value.get("text")
        if isinstance(text_value, str):
            return text_value.strip()
        value_field = value.get("value")
        if isinstance(value_field, str):
            return value_field.strip()
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    return str(value).strip()


def normalize_title(value: Any) -> str:
    if not isinstance(value, str):
        return DEFAULT_CONVERSATION_TITLE
    title = value.strip()
    if not title:
        return DEFAULT_CONVERSATION_TITLE
    return title[:255]


def infer_title_from_content(content: str) -> str:
    cleaned = " ".join(content.split()).strip()
    if not cleaned:
        return DEFAULT_CONVERSATION_TITLE
    return cleaned[:255]


def serialize_datetime(value: Any) -> Optional[str]:
    return value.isoformat() if value is not None else None


def serialize_conversation(row: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "id": row["id"],
        "title": row["title"],
        "created_at": serialize_datetime(row["created_at"]),
        "updated_at": serialize_datetime(row["updated_at"]),
    }


def serialize_message(row: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "id": row["id"],
        "conversation_id": row["conversation_id"],
        "role": row["role"],
        "content": row["content"],
        "reasoning": row["reasoning"],
        "created_at": serialize_datetime(row["created_at"]),
    }


@lru_cache(maxsize=1)
def get_ai_client() -> OpenAI:
    token = get_env_str("FRIENDLI_TOKEN", required=True)
    base_url = get_env_str("FRIENDLI_BASE_URL", "")
    timeout = httpx.Timeout(
        connect=float(get_env_int("AI_TIMEOUT_CONNECT_SECONDS", 10, 1, 300)),
        read=float(get_env_int("AI_TIMEOUT_READ_SECONDS", 180, 1, 3600)),
        write=float(get_env_int("AI_TIMEOUT_WRITE_SECONDS", 60, 1, 3600)),
        pool=float(get_env_int("AI_TIMEOUT_POOL_SECONDS", 30, 1, 3600)),
    )
    return OpenAI(
        api_key=token,
        base_url=base_url,
        timeout=timeout,
        max_retries=get_env_int("AI_MAX_RETRIES", 2, 0, 10),
    )


def get_ai_model() -> str:
    return get_env_str("AI_MODEL", "zai-org/GLM-5")


def get_system_prompt() -> str:
    prompt = os.getenv("SYSTEM_PROMPT", "You are a helpful assistant.")
    prompt = prompt.strip()
    return prompt or "You are a helpful assistant."


def build_messages_for_ai(history: List[Dict[str, Any]], user_content: str) -> List[Dict[str, str]]:
    messages_for_ai: List[Dict[str, str]] = [{"role": "system", "content": get_system_prompt()}]
    for item in history:
        role = item.get("role")
        content = normalize_text(item.get("content"))
        if role in {"user", "assistant"} and content:
            messages_for_ai.append({"role": role, "content": content})
    messages_for_ai.append({"role": "user", "content": user_content})
    return messages_for_ai


def request_ai_completion(messages_for_ai: List[Dict[str, str]]) -> Dict[str, Optional[str]]:
    completion = get_ai_client().chat.completions.create(
        model=get_ai_model(),
        messages=messages_for_ai,
        max_completion_tokens=get_env_int("AI_MAX_COMPLETION_TOKENS", 4096, 1, 65536),
        extra_body={
            "parse_reasoning": True,
            "chat_template_kwargs": {"enable_thinking": True},
        },
    )
    choices = getattr(completion, "choices", None)
    if not choices:
        raise ApiError("AI provider returned no choices", 502)
    choice = choices[0]
    message = getattr(choice, "message", None)
    if message is None:
        raise ApiError("AI provider returned no message", 502)
    ai_content = normalize_text(getattr(message, "content", None))
    ai_reasoning = normalize_text(getattr(message, "reasoning_content", None))
    if not ai_content and ai_reasoning:
        ai_content = ai_reasoning
    if not ai_content:
        raise ApiError("AI provider returned empty content", 502)
    return {"content": ai_content, "reasoning": ai_reasoning or None}


@app.before_request
def before_request_initialize() -> None:
    if request.path.startswith("/api/"):
        initialize_once()


@app.errorhandler(ApiError)
def handle_api_error(error: ApiError):
    return jsonify({"error": error.message}), error.status_code


@app.errorhandler(HTTPException)
def handle_http_exception(error: HTTPException):
    if request.path.startswith("/api/"):
        return jsonify({"error": error.description}), error.code
    return error


@app.errorhandler(Exception)
def handle_unexpected_error(error: Exception):
    app.logger.exception("Unhandled exception")
    if request.path.startswith("/api/"):
        return jsonify({"error": "Internal server error"}), 500
    raise error


@app.route("/")
def index():
    index_path = os.path.join(BASE_DIR, "index.html")
    if not os.path.isfile(index_path):
        raise HTTPException(description="index.html not found")
    return send_from_directory(BASE_DIR, "index.html")


@app.route("/api/conversations", methods=["GET"])
def list_conversations():
    limit = parse_query_int("limit", 200, 1, 1000)
    offset = parse_query_int("offset", 0, 0, 1000000)
    with db_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, title, created_at, updated_at
                FROM conversations
                ORDER BY updated_at DESC, id DESC
                LIMIT %s OFFSET %s
                """,
                (limit, offset),
            )
            rows = cur.fetchall()
    return jsonify([serialize_conversation(row) for row in rows])


@app.route("/api/conversations", methods=["POST"])
def create_conversation():
    data = parse_json_body()
    raw_title = data.get("title")
    title = normalize_title(raw_title)
    auto_title = 1 if title == DEFAULT_CONVERSATION_TITLE and not (isinstance(raw_title, str) and raw_title.strip()) else 0
    with db_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO conversations (title, auto_title)
                VALUES (%s, %s)
                """,
                (title, auto_title),
            )
            conversation_id = cur.lastrowid
            cur.execute(
                """
                SELECT id, title, created_at, updated_at
                FROM conversations
                WHERE id = %s
                """,
                (conversation_id,),
            )
            row = cur.fetchone()
        conn.commit()
    if row is None:
        raise ApiError("Failed to create conversation", 500)
    return jsonify(serialize_conversation(row)), 201


@app.route("/api/conversations/<int:conv_id>", methods=["DELETE"])
def delete_conversation(conv_id: int):
    with db_connection() as conn:
        with conn.cursor() as cur:
            affected = cur.execute("DELETE FROM conversations WHERE id = %s", (conv_id,))
        conn.commit()
    if affected == 0:
        return jsonify({"error": "Not found"}), 404
    return "", 204


@app.route("/api/conversations/<int:conv_id>/messages", methods=["GET"])
def get_messages(conv_id: int):
    limit = parse_query_int("limit", 1000, 1, 5000)
    offset = parse_query_int("offset", 0, 0, 1000000)
    with db_connection() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM conversations WHERE id = %s", (conv_id,))
            exists = cur.fetchone()
            if exists is None:
                return jsonify({"error": "Not found"}), 404
            cur.execute(
                """
                SELECT id, conversation_id, role, content, reasoning, created_at
                FROM messages
                WHERE conversation_id = %s
                ORDER BY created_at ASC, id ASC
                LIMIT %s OFFSET %s
                """,
                (conv_id, limit, offset),
            )
            rows = cur.fetchall()
    return jsonify([serialize_message(row) for row in rows])


@app.route("/api/conversations/<int:conv_id>/messages", methods=["POST"])
def send_message(conv_id: int):
    data = parse_json_body()
    raw_content = data.get("content")
    if not isinstance(raw_content, str):
        raise ApiError("content must be a string", 400)
    user_content = raw_content.strip()
    if not user_content:
        raise ApiError("Content required", 400)

    history_limit = get_env_int("AI_HISTORY_MESSAGES", 100, 1, 1000)

    with db_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, title, auto_title
                FROM conversations
                WHERE id = %s
                """,
                (conv_id,),
            )
            conv = cur.fetchone()
            if conv is None:
                return jsonify({"error": "Conversation not found"}), 404

            cur.execute(
                """
                SELECT role, content
                FROM (
                    SELECT role, content, created_at, id
                    FROM messages
                    WHERE conversation_id = %s
                    ORDER BY created_at DESC, id DESC
                    LIMIT %s
                ) AS recent_messages
                ORDER BY created_at ASC, id ASC
                """,
                (conv_id, history_limit),
            )
            history = cur.fetchall()

    messages_for_ai = build_messages_for_ai(history, user_content)
    ai_response = request_ai_completion(messages_for_ai)

    with db_connection() as conn:
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT id, auto_title
                    FROM conversations
                    WHERE id = %s
                    FOR UPDATE
                    """,
                    (conv_id,),
                )
                locked_conv = cur.fetchone()
                if locked_conv is None:
                    conn.rollback()
                    return jsonify({"error": "Conversation not found"}), 404

                cur.execute(
                    """
                    INSERT INTO messages (conversation_id, role, content, reasoning)
                    VALUES (%s, %s, %s, %s)
                    """,
                    (conv_id, "user", user_content, None),
                )

                cur.execute(
                    """
                    INSERT INTO messages (conversation_id, role, content, reasoning)
                    VALUES (%s, %s, %s, %s)
                    """,
                    (conv_id, "assistant", ai_response["content"], ai_response["reasoning"]),
                )
                assistant_message_id = cur.lastrowid

                if int(locked_conv["auto_title"]) == 1:
                    cur.execute(
                        """
                        UPDATE conversations
                        SET title = %s,
                            auto_title = 0,
                            updated_at = CURRENT_TIMESTAMP(6)
                        WHERE id = %s
                        """,
                        (infer_title_from_content(user_content), conv_id),
                    )
                else:
                    cur.execute(
                        """
                        UPDATE conversations
                        SET updated_at = CURRENT_TIMESTAMP(6)
                        WHERE id = %s
                        """,
                        (conv_id,),
                    )

                cur.execute(
                    """
                    SELECT id, conversation_id, role, content, reasoning, created_at
                    FROM messages
                    WHERE id = %s
                    """,
                    (assistant_message_id,),
                )
                new_msg = cur.fetchone()

            conn.commit()
        except Exception:
            conn.rollback()
            raise

    if new_msg is None:
        raise ApiError("Failed to persist assistant message", 500)

    return jsonify(serialize_message(new_msg)), 201


if __name__ == "__main__":
    initialize_once()
    port = get_env_int("PORT", 8080, 1, 65535)
    app.run(host="0.0.0.0", port=port, debug=False, threaded=True)
